  INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id)
  VALUES ('d5d2bc50-6c45-4dd8-8dbb-b9fd938493fc'::uuid, tid, 'primitive', 'p22 · Transition Plan
16
Engage Air Force Key Stake Holders:', 'Transition Plan
16
Engage Air Force Key Stake Holders:
Immobileyes will engage with the Key Stakeholders in Air Force Security Forces Center, Air Force
Installation and Mission Support Center, and the Air Logistics Centers, to support the translation of the
technology to a fieldable solution. Letter of Support provided by the Air Force Security Forces Center.
Immobileyes will engage with the following Air Force stakeholders to support development and
execution of the transition plan:
Air Force End-Users: 	Security Forces Squadrons, Air Force Special Operators, Air Logistics
Centers, Installation and Base Management, and others.
Contracting: 	Immobileyes will meet with the contracting team to discuss support for a
Phase II project and implementation of a Phase III acquisition contract.
Leadership: 	The feasibility study will be briefed to leadership personnel within the
participating Air Force organizations to ensure transition support.
Other Stakeholders: 	Immobileyes with collaborate with other Air Force stakeholders as
identified and referred by our existing partners.
Topic: X23.5_CSO 	Proposal Number: FX235-CSO1-0859
“Base-Wide Counter-UAS and Defeat of Drone Surveillance Utilizing Innovative LED-Based Directed Energy System”', '[{"id":"f5701466-5b73-4d20-8d2f-d3d10fc6a0cf","type":"text_block","style":{},"content":{"text":"Transition Plan\n16\nEngage Air Force Key Stake Holders:\nImmobileyes will engage with the Key Stakeholders in Air Force Security Forces Center, Air Force\nInstallation and Mission Support Center, and the Air Logistics Centers, to support the translation of the\ntechnology to a fieldable solution. Letter of Support provided by the Air Force Security Forces Center.\nImmobileyes will engage with the following Air Force stakeholders to support development and\nexecution of the transition plan:\nAir Force End-Users: \tSecurity Forces Squadrons, Air Force Special Operators, Air Logistics\nCenters, Installation and Base Management, and others.\nContracting: \tImmobileyes will meet with the contracting team to discuss support for a\nPhase II project and implementation of a Phase III acquisition contract.\nLeadership: \tThe feasibility study will be briefed to leadership personnel within the\nparticipating Air Force organizations to ensure transition support.\nOther Stakeholders: \tImmobileyes with collaborate with other Air Force stakeholders as\nidentified and referred by our existing partners.\nTopic: X23.5_CSO \tProposal Number: FX235-CSO1-0859\n“Base-Wide Counter-UAS and Defeat of Drone Surveillance Utilizing Innovative LED-Based Directed Energy System”"},"history":[],"provenance":{"source":"imported"},"library_eligible":true}]'::jsonb, NULL, 173, 1248, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', '31c0c32b-a7c5-47fc-817b-55a3b84f960f'::uuid, NULL, NULL, '686842de-ae88-44ac-b724-8e550f079e3e'::uuid, 'tenant', '2026-08-18T22:42:56.670Z'::timestamptz, '2026-08-18T22:42:56.670Z'::timestamptz, 'admin', uid, '[{"blockIds":["b22"],"sourceAtomId":"61cb1be6-93f1-4af6-9561-8b8fb5b5e554"}]'::jsonb, NULL)
