  VALUES ('70f30e3f-872d-4738-8641-bafd9ce6650f'::uuid, tid, 'primitive', 'p17 · Proposal Number: N26BX-NP002-0450
Open Topic Number: 	', 'Proposal Number: N26BX-NP002-0450
