  INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id)
  VALUES ('9abaf288-eba4-40ea-a986-ed438e12610a'::uuid, tid, 'primitive', 'Quick Reference
DO
● 	Include only truthful information in
p', 'Quick Reference
DO
● 	Include only truthful information in
proposals re: company size, facilities,
personnel, consultants, subawards,
supporters, etc.
● 	Include only truthful certifications as to
eligibility requirements at each phase of
the award, from proposal to reports.
● 	Read the applicable rules and follow
them. Certify on multiple occasions that
you have done so.
● 	If you have questions, ask the
Contracting Officer!
DON’T
● 	Certify to things you aren’t sure about
(or know to be false).
● 	Make up bios or publications for people
in proposals.
● 	Plagiarize, fabricate, or falsify text or
figures in proposals or reports.
● 	Describe in proposals facilities,
equipment or employees that you don’t
have.
● 	Alter or fabricate letters of support.
● 	Create fake accounting documents.
● 	Use award funds for personal expenses
(except for allowed profit and
legitimately earned salary).
Distribution A - Approved for Public Release | Office of Naval Research DCN #: 43-7334-20 -- 24 of 25 -- Fraud, Waste, and Abuse
(FWA) Summary
The Department of the Navy: Takes occurrences of FWA seriously. Continues efforts to prevent FWA. Hosts an SBIR/STTR FWA webpage to promote awareness here navysbir.com/fwa.htm.', '[{"id":"52d4337d-7d98-4080-ae7d-014000793ed5","type":"text_block","style":{},"content":{"text":"Quick Reference\nDO\n● \tInclude only truthful information in\nproposals re: company size, facilities,\npersonnel, consultants, subawards,\nsupporters, etc.\n● \tInclude only truthful certifications as to\neligibility requirements at each phase of\nthe award, from proposal to reports.\n● \tRead the applicable rules and follow\nthem. Certify on multiple occasions that\nyou have done so.\n● \tIf you have questions, ask the\nContracting Officer!\nDON’T\n● \tCertify to things you aren’t sure about\n(or know to be false).\n● \tMake up bios or publications for people\nin proposals.\n● \tPlagiarize, fabricate, or falsify text or\nfigures in proposals or reports.\n● \tDescribe in proposals facilities,\nequipment or employees that you don’t\nhave.\n● \tAlter or fabricate letters of support.\n● \tCreate fake accounting documents.\n● \tUse award funds for personal expenses\n(except for allowed profit and\nlegitimately earned salary).\nDistribution A - Approved for Public Release | Office of Naval Research DCN #: 43-7334-20"},"history":[{"action":"created","actor_id":"system:import","timestamp":"2026-08-18T22:46:46.072Z","actor_name":"Document Import"}],"provenance":{"source":"imported","drafted_at":"2026-08-18T22:46:46.072Z","drafted_by":"system:import"},"library_eligible":true},{"id":"0fa7fbf7-9b33-4c2c-b0fe-256df2c26d90","type":"text_block","style":{},"content":{"text":"-- 24 of 25 --"},"history":[{"action":"created","actor_id":"system:import","timestamp":"2026-08-18T22:46:46.072Z","actor_name":"Document Import"}],"provenance":{"source":"imported","drafted_at":"2026-08-18T22:46:46.072Z","drafted_by":"system:import"},"library_eligible":true},{"id":"d6c741bc-71e7-4686-be7d-ec63c880e2da","type":"text_block","style":{},"content":{"text":"Fraud, Waste, and Abuse\n(FWA) Summary\nThe Department of the Navy:"},"history":[{"action":"created","actor_id":"system:import","timestamp":"2026-08-18T22:46:46.072Z","actor_name":"Document Import"}],"provenance":{"source":"imported","drafted_at":"2026-08-18T22:46:46.072Z","drafted_by":"system:import"},"library_eligible":true},{"id":"71b4a57f-d64e-4dc0-b510-34a8f4363540","type":"bulleted_list","style":{},"content":{"items":[{"text":"Takes occurrences of FWA seriously."},{"text":"Continues efforts to prevent FWA."},{"text":"Hosts an SBIR/STTR FWA webpage to promote awareness"}]},"history":[{"action":"created","actor_id":"system:import","timestamp":"2026-08-18T22:46:46.072Z","actor_name":"Document Import"}],"provenance":{"source":"imported","drafted_at":"2026-08-18T22:46:46.072Z","drafted_by":"system:import"},"library_eligible":true},{"id":"4d9bcf4b-ab02-4774-9faf-82ce79ad8ed2","type":"text_block","style":{},"content":{"text":"here navysbir.com/fwa.htm."},"history":[{"action":"created","actor_id":"system:import","timestamp":"2026-08-18T22:46:46.072Z","actor_name":"Document Import"}],"provenance":{"source":"imported","drafted_at":"2026-08-18T22:46:46.072Z","drafted_by":"system:import"},"library_eligible":true}]'::jsonb, NULL, 190, 1217, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', '684d8917-6a86-4eeb-806d-4db1cd3a655f'::uuid, NULL, NULL, '686842de-ae88-44ac-b724-8e550f079e3e'::uuid, 'tenant', '2026-08-18T22:46:46.375Z'::timestamptz, '2026-08-18T22:46:46.375Z'::timestamptz, 'admin', uid, '[{"blockIds":["b23"],"sourceAtomId":"c99370d2-7299-4910-a2da-03a237394599"}]'::jsonb, NULL)
